REVOKE EXECUTE ON FUNCTION public.record_staff_crm_view(text,jsonb) FROM authenticated;
CREATE OR REPLACE FUNCTION public.record_staff_crm_view(_tab text,_filters jsonb DEFAULT '{}'::jsonb,_user_id uuid DEFAULT NULL) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE me uuid; BEGIN SELECT id INTO me FROM public.admin_users WHERE user_id=_user_id AND is_active AND archived_at IS NULL; IF me IS NULL THEN RAISE EXCEPTION 'Active staff required'; END IF; IF _tab IS NULL OR _tab !~ '^[a-z0-9-]{1,60}$' THEN RAISE EXCEPTION 'Invalid page'; END IF; INSERT INTO public.staff_crm_view_observations(staff_admin_id,tab,filters) VALUES(me,_tab,public.staff_crm_safe_filters(_filters)); END $$;
REVOKE ALL ON FUNCTION public.record_staff_crm_view(text,jsonb,uuid) FROM PUBLIC,anon,authenticated; GRANT EXECUTE ON FUNCTION public.record_staff_crm_view(text,jsonb,uuid) TO service_role;
CREATE OR REPLACE FUNCTION public.staff_crm_redact(_row jsonb) RETURNS jsonb LANGUAGE sql IMMUTABLE SET search_path=public AS $$ SELECT coalesce(jsonb_object_agg(key,CASE WHEN jsonb_typeof(value)='object' THEN public.staff_crm_redact(value) WHEN jsonb_typeof(value)='array' THEN (SELECT coalesce(jsonb_agg(CASE WHEN jsonb_typeof(v)='object' THEN public.staff_crm_redact(v) ELSE v END),'[]'::jsonb) FROM jsonb_array_elements(value) v) ELSE value END),'{}'::jsonb) FROM jsonb_each(_row) WHERE key !~* '(password|token|secret|api.?key|authorization|cookie|credential)'; $$;
REVOKE ALL ON FUNCTION public.staff_crm_redact(jsonb) FROM PUBLIC,anon,authenticated;
CREATE OR REPLACE FUNCTION public.staff_archive_copy_table(_archive_id uuid,_table text) RETURNS integer LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE a record; src record; n integer:=0; cnt integer; BEGIN SELECT * INTO a FROM public.staff_leaver_archives WHERE id=_archive_id FOR UPDATE; IF a.id IS NULL OR a.status<>'building' THEN RETURN 0; END IF; IF a.table_counts ? _table THEN RETURN 0; END IF; FOR src IN SELECT * FROM public.staff_archive_sources() s WHERE s.table_name=_table LOOP
IF src.data_type='uuid' THEN EXECUTE format('INSERT INTO public.staff_leaver_archive_items(archive_id,source_table,matched_column,row_data) SELECT $1,%L,%L,public.staff_crm_redact(to_jsonb(t)) FROM public.%I t WHERE t.%I=ANY($2)',_table,src.column_name,_table,src.column_name) USING _archive_id,ARRAY[a.admin_user_id,a.auth_user_id]::uuid[]; ELSE EXECUTE format('INSERT INTO public.staff_leaver_archive_items(archive_id,source_table,matched_column,row_data) SELECT $1,%L,%L,public.staff_crm_redact(to_jsonb(t)) FROM public.%I t WHERE t.%I=ANY($2)',_table,src.column_name,_table,src.column_name) USING _archive_id,ARRAY[a.admin_user_id::text,a.auth_user_id::text]; END IF; GET DIAGNOSTICS cnt=ROW_COUNT; n:=n+cnt; END LOOP; UPDATE public.staff_leaver_archives SET table_counts=table_counts||jsonb_build_object(_table,n),total_records=total_records+n WHERE id=_archive_id; RETURN n; END $$;